namespace TheEasyWayForDrivers.Core.Drivers;

/// <summary>
/// Only specific, same-token USBSTOR PnP models may correlate WUA/INF to a
/// physical device. USBSTOR\GenDisk, Disk, RAW and vendor-only identifiers
/// are shared compatible IDs generated by Windows USBSTOR.SYS.
/// This is read-only evidence, never installation authorization.
/// </summary>
public static class UsbStorPnpMatchPolicy
{
    private static readonly string[] TypeNames =
    [
        "UsbstorOther", "Sequential", "SFloppy", "Optical",
        "Changer", "CdRom", "Disk", "Worm", "Other"
    ];

    public static bool IsSpecificHardwareId(string? id)
    {
        if (!PnpIdentifierFallback.IsStrictSingleId(id) ||
            !id!.StartsWith(@"USBSTOR\", StringComparison.OrdinalIgnoreCase))
            return false;

        var key = id.AsSpan(@"USBSTOR\".Length);
        if (key.StartsWith("Gen", StringComparison.OrdinalIgnoreCase) ||
            key.Equals("RAW", StringComparison.OrdinalIgnoreCase))
            return false;

        // USBSTOR.SYS also generates untyped v(8)p(16)r(1) identifiers.
        // Keep these exact IDs, but never mistake a bare padded v(8)
        // or a generic class token for a unique drive.
        foreach (var type in TypeNames)
        {
            if (!key.StartsWith(type, StringComparison.OrdinalIgnoreCase))
                continue;

            var suffix = key[type.Length..];
            if (suffix.StartsWith("&Ven_", StringComparison.OrdinalIgnoreCase))
                return IsStructuredVendorProduct(suffix);
            return IsPaddedVendorProduct(suffix, hasType: true);
        }

        return IsPaddedVendorProduct(key, hasType: false);
    }

    private static bool IsPaddedVendorProduct(
        ReadOnlySpan<char> model, bool hasType)
    {
        // Microsoft: t*v(8)p(16)[r(4)], or untyped v(8)p(16)r(1).
        // Short t*v(8) is vendor-only, shared across several products.
        if (model.Length != 24 && model.Length != 28 &&
            !(model.Length == 25 && !hasType))
            return false;

        foreach (var character in model)
            if (!char.IsAsciiLetterOrDigit(character) && character != '_')
                return false;

        return HasRealText(model[..8]) && HasRealText(model.Slice(8, 16));
    }

    private static bool IsStructuredVendorProduct(ReadOnlySpan<char> suffix)
    {
        // Some reported USBSTOR identifiers use a structured
        // Disk&Ven_<name>&Prod_<name>[&Rev_<version>] spelling.
        // Require BOTH vendor and product; a malformed trailing field
        // cannot be converted into a valid match.
        const string vendor = "&Ven_";
        const string product = "&Prod_";
        const string revision = "&Rev_";
        var rest = suffix[vendor.Length..];
        var productAt = rest.IndexOf(product, StringComparison.OrdinalIgnoreCase);
        if (productAt < 1 || productAt > 32)
            return false;

        var vendorName = rest[..productAt];
        rest = rest[(productAt + product.Length)..];
        var revisionAt = rest.IndexOf(revision, StringComparison.OrdinalIgnoreCase);
        var productName = revisionAt < 0 ? rest : rest[..revisionAt];
        if (productName.Length is < 1 or > 64 ||
            !IsStructuredText(vendorName) ||
            !IsStructuredText(productName))
            return false;

        if (revisionAt < 0)
            return true;

        var revisionText = rest[(revisionAt + revision.Length)..];
        return revisionText.Length is >= 1 and <= 8 &&
            IsStructuredText(revisionText);
    }

    private static bool IsStructuredText(ReadOnlySpan<char> value)
    {
        var hasAscii = false;
        foreach (var c in value)
        {
            if (char.IsAsciiLetterOrDigit(c))
                hasAscii = true;
            else if (c is not ('_' or '-' or '.'))
                return false;
        }
        return hasAscii;
    }

    private static bool HasRealText(ReadOnlySpan<char> value)
    {
        foreach (var character in value)
            if (char.IsAsciiLetterOrDigit(character))
                return true;
        return false;
    }
}
